/**
 * Trait for document renderers that convert extraction results to output strings.
 *
 * Renderers are typically stateless converters that transform extracted
 * content into a specific output format (Markdown, HTML, Djot, plain text,
 * etc.). They participate in the standard `Plugin`
 * lifecycle so custom renderers can be registered from any supported binding
 * language.
 *
 * The format name is exposed via `Plugin.name`. For stateless renderers
 * the `Plugin` lifecycle methods (`version`, `initialize`, `shutdown`) all
 * take no-op defaults and need not be overridden.
 *
 * # Thread Safety
 *
 * Renderers must be `Send + Sync` (inherited from `Plugin`).
 */
export interface Renderer {
  name(): string;
  version?(): string;
  initialize?(): void;
  shutdown?(): void;
  /**
   * Binding-safe rendering entry point for foreign-language plugin bridges.
   *
   * Accepts one public extraction result and returns the rendered output.
   */
  renderResult?(result?: ExtractedDocument | undefined | null): string;
}

/**
 * A single document returned by the reranker, with its position in the input and score.
 *
 * `index` maps back to the caller's original document list, so metadata arrays
 * (e.g. IDs, paths) can be reordered without passing them through the reranker.
 */
export interface RerankedDocument {
  /** Position of this document in the original input `documents` slice. */
  readonly index: number;
  /** Relevance score in `[0, 1]`. Higher means more relevant to the query. */
  readonly score: number;
  /** The document text. */
  readonly document: string;
}

/**
 * Trait for in-process reranker backend plugins.
 *
 * Cross-encoders score `(query, document)` pairs jointly and return a
 * raw logit per document. The crate-level `rerank` dispatcher applies
 * sigmoid to convert logits to `[0, 1]` scores, sorts descending by score,
 * and truncates to `top_k`.
 *
 * Async to match the convention used by `EmbeddingBackend`
 * and other plugin traits. Host-language bridges wrap their synchronous
 * host callables in `spawn_blocking` or the equivalent.
 *
 * # Thread safety
 *
 * Backends must be `Send + Sync + 'static`. They are stored in
 * `Arc<dyn RerankerBackend>` and may be called concurrently from xberg's
 * dispatcher. If the backend's underlying model is not thread-safe, the
 * backend itself must serialize access internally (e.g. via `Mutex<Inner>`).
 *
 * # Contract
 *
 * - `rerank(query, documents)` MUST return exactly `documents.len()` scores.
 *   The dispatcher validates this before sorting and returning to callers;
 *   a non-conforming backend surfaces as a `XbergError.Validation`, not
 *   a panic.
 * - Scores are raw logits in any range — callers must NOT assume `[0, 1]`.
 *   The dispatcher applies sigmoid before sorting.
 * - `rerank` may be called from any thread. Its future must be `Send`
 *   (enforced by `async_trait` when `#[async_trait]` is used on non-WASM
 *   targets).
 * - `shutdown()` (inherited from `Plugin`) may be invoked
 *   concurrently with an in-flight `rerank()` call. Implementations must
 *   tolerate this — letting in-flight calls finish via the `Arc` reference
 *   and only releasing shared state that isn't needed by `rerank`.
 *
 * # Runtime
 *
 * The synchronous `rerank` entry uses
 * `tokio.task.block_in_place` to await the trait's async `rerank`, which
 * requires a multi-thread tokio runtime. Callers running inside a
 * `current_thread` runtime must use `rerank_async` instead.
 */
export interface RerankerBackend {
  name(): string;
  version?(): string;
  initialize?(): void;
  shutdown?(): void;
  /**
   * Score a list of documents against a query.
   *
   * Returns one raw logit per document in the same order as the input.
   * The dispatcher applies sigmoid to convert to `[0, 1]` scores.
   * @throws Implementations should return `Plugin` for
   * backend-specific failures. The dispatcher validates the returned length
   * against `documents.len()` before sorting.
   */
  rerank(query: string, documents: Array<string>): Promise<Array<number>>;
}

/**
 * Configuration for the reranking pipeline.
 *
 * Controls which model to use, how many results to return, and download/cache
 * behavior for local ONNX models.
 */
export interface RerankerConfig {
  /** The reranker model to use (defaults to "balanced" preset if not specified). */
  readonly model?: RerankerModelType;
  /**
   * Return at most this many documents. `None` returns all.
   *
   * Applied after sorting by score, so the highest-scoring documents are kept.
   */
  readonly topK?: number;
  /** Batch size for local ONNX cross-encoder inference. */
  readonly batchSize?: number;
  /**
   * Show model download progress (local ONNX path only).
   *
   * When enabled, transfer progress for the model, tokenizer and config files is reported at
   * `info` level on the `xberg.model_download` target while they download (#279). A warm
   * Hugging Face cache transfers nothing and so reports nothing. Ignored by
   * `RerankerModelType.Llm` and `RerankerModelType.Plugin`, which download no model.
   */
  readonly showDownloadProgress?: boolean;
  /**
   * Optional alternate Hugging Face cache root for model files.
   *
   * When unset, hf-hub follows the standard Hugging Face environment and
   * platform cache conventions.
   */
  readonly cacheDir?: string;
  /**
   * Hardware acceleration for the reranker ONNX model.
   *
   * Controls which execution provider (CPU, CUDA, CoreML, TensorRT) is used for
   * local inference. Defaults to `None` (auto-select per platform).
   */
  readonly acceleration?: AccelerationConfig;
  /**
   * Maximum wall-clock duration (in seconds) for a single `rerank()` call when
   * using `RerankerModelType.Plugin`.
   *
   * Applies only to the in-process plugin path — protects against hung
   * host-language backends. On timeout, the dispatcher returns
   * `Plugin` instead of blocking forever.
   *
   * `None` disables the timeout. The default (60 seconds) is conservative
   * for common in-process inference; increase for large document sets on slow
   * hardware.
   */
  readonly maxRerankDurationSecs?: number;
}

/**
 * Selects how a local ONNX reranker's raw output tensor is turned into a score.
 *
 * - `RerankerHead.CrossEncoder` — classic single-logit cross-encoder head:
 *   the model emits `[batch, 1]` (or `[batch]`) logits; the caller applies
 *   sigmoid to get a `[0, 1]` score. This is the original, unchanged path.
 * - `RerankerHead.Qwen3Generative` — Qwen3 generative-reranker head: the
 *   model emits `[batch, seq, vocab]` logits; the score is `P("yes")` read
 *   from the last token's logits over the "yes"/"no" vocabulary entries,
 *   via a softmax over those two logits. Already a `[0, 1]` probability —
 *   no sigmoid is applied.
 */
export declare enum RerankerHead {
  /** Single-logit cross-encoder head (sigmoid applied by the caller). */
  CrossEncoder = "cross_encoder",
  /** Qwen3 generative-reranker head (softmax over yes/no token logits). */
  Qwen3Generative = "qwen_3_generative",
}

/** Reranker model types supported by Xberg. */
